aqui tienes un ejemplo de bubble sort en python:

```python
def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

lista = [64, 34, 25, 12, 22, 11, 90]
print(bubble_sort(lista))
```

aqui tienes un ejemplo de bubble sort en javascript:

```javascript
function bubblesort(arr) {
    let n = arr.length;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                let temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
    return arr;
}

let array = [64, 34, 25, 12, 22, 11, 90];
console.log(bubblesort(array));
```

aqui tienes un ejemplo de busqueda binaria en python:

```python
def binary_search(arr, x):
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            return mid
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return -1

array = [1, 3, 5, 7, 9, 11]
print(binary_search(array, 5))
```

aqui tienes un ejemplo de busqueda binaria en javascript:

```javascript
function binarysearch(arr, x) {
    let low = 0, high = arr.length - 1;
    while (low <= high) {
        let mid = math.floor((low + high) / 2);
        if (arr[mid] === x) return mid;
        else if (arr[mid] < x) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

let array = [1, 3, 5, 7, 9, 11];
console.log(binarysearch(array, 5));
```

aqui tienes un ejemplo de quicksort en javascript:

```javascript
function quicksort(arr) {
    if (arr.length <= 1) return arr;
    let pivot = arr[math.floor(arr.length / 2)];
    let left = arr.filter(x => x < pivot);
    let middle = arr.filter(x => x === pivot);
    let right = arr.filter(x => x > pivot);
    return [...quicksort(left), ...middle, ...quicksort(right)];
}

let array = [3, 6, 8, 10, 1, 2, 1];
console.log(quicksort(array));
```

